import sys

def main():
    s = sys.stdin.readline().strip()
    n = len(s)

    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n):
        if i >= 2 and dp[i - 2]:
            if i + 2 <= n:
                dp[i] = True
        if i >= 3 and dp[i - 3]:
            if i + 3 <= n:
                dp[i] = True

    valid_suffixes = set()

    for i in range(n - 1, 1, -1):
        if i == n:
            continue

        if i >= 2 and dp[i - 2]:
            suffix2 = s[i:i+2]
            if i + 2 <= n:
                if i + 2 == n:
                    valid_suffixes.add(suffix2)

        if i >= 3 and dp[i - 3]:
            suffix3 = s[i:i+3]
            if i + 3 <= n:
                if i + 3 == n:
                    valid_suffixes.add(suffix3)

    sorted_suffixes = sorted(valid_suffixes)
    print(len(sorted_suffixes))
    for suf in sorted_suffixes:
        print(suf)

if __name__ == "__main__":
    main()
